# Blocks of 6 are sparse; find maximal connected components of 6 in output (pair1), look at their relation to input.
from collections import deque
def comps(O,v):
    H,W=len(O),len(O[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if O[r][c]==v and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((-1,0),(1,0),(0,-1),(0,1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and O[ny][nx]==v and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append(cells)
    return out
